14	    {
15	        var vonZeitpunkt = von?.ToDateTime(TimeOnly.MinValue);
16	        var bisZeitpunkt = bis is null
17	            ? (DateTime?)null
18	            : bis == DateOnly.MaxValue
19	                ? DateTime.MaxValue
20	                : bis.Value.AddDays(1).ToDateTime(TimeOnly.MinValue);
21	
