23	            from e in db.Events
24	            join r in db.Rooms on e.RoomId equals r.Id
25	            join v in db.Venues on r.VenueId equals v.Id
26	            where (vonZeitpunkt == null || e.Zeitpunkt >= vonZeitpunkt) && (bisZeitpunkt == null || e.Zeitpunkt < bisZeitpunkt)
