{
    var vonZeitpunkt = von?.ToDateTime(TimeOnly.MinValue);
    var bisZeitpunkt = bis is null
        ? (DateTime?)null
        : bis == DateOnly.MaxValue
            ? DateTime.MaxValue
            : bis.Value.AddDays(1).ToDateTime(TimeOnly.MinValue);

    return await (
        from e in db.Events
        join r in db.Rooms on e.RoomId equals r.Id
